import{_ as o,l as s,o as e,c as i,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"缺页与置换","description":"","frontmatter":{"title":"缺页与置换","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/page-replace.md","filePath":"cs/page-replace.md","lastUpdated":1789023840000}'),h={name:"cs/page-replace.md"};function m(_,a,E,B,u,A){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="缺页与置换" tabindex="-1">缺页与置换 <a class="header-anchor" href="#缺页与置换" aria-label="Permalink to &quot;缺页与置换&quot;">​</a></h1><div class="epigraph"><p>物理页不够时，必须选出一页写回或丢弃，把帧交给缺页者；算法决定抖动还是工作。</p><footer>—— 据 Belady, A study of replacement algorithms for a virtual-storage computer, IBM Systems Journal 1966 整理</footer></div><p><a href="/cs/tlb-shootdown">上一课</a>在有空闲帧时补页。帧用尽后，再缺页必须<strong>置换</strong>。缺口不是再解释陷入入口，而是选牺牲页：FIFO、最优、LRU 与时钟近似。本课不把写时复制和文件映射提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最优算法淘汰「未来最久不用」的页，离线才知道。FIFO 实现简单，可发生 Belady 异常：给更多帧，缺页反而增加。LRU 贴近局部性，要硬件或软件记使用时间。缺口是：在线算法如何逼近 LRU，以及脏页必须先写回再腾帧——写回接后课缓冲，本课只承认脏位。</p><p>本课不把 Linux 的 LRU 活跃/非活跃链表细节当考纲。</p><p><span class="marginnote">时钟算法：页表访问位置位，指针转圈，遇到未访问者淘汰，遇到访问者清位再走。是 LRU 的廉价近似。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缺页且无空闲：按策略选页；若脏则加入写回；取消原页表映射并冲 <a href="/cs/tlb-translate">TLB</a>；把帧交给新页。全局置换在全系统选；局部置换在该进程配额内选。工作集若大于物理内存，任何算法都会抖动：大部分时间在换页。</p>',9)),(e(),n(c,null,{default:r(()=>[d(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NF%5B%22%E6%97%A0%E7%A9%BA%E9%97%B2%E5%B8%A7%22%5D%20--%3E%20PICK%5B%22%E9%80%89%E7%89%BA%E7%89%B2%E9%A1%B5%22%5D%0A%20%20PICK%20--%3E%20DIRTY%5B%22%E8%84%8F%E5%88%99%E5%86%99%E5%9B%9E%22%5D%0A%20%20DIRTY%20--%3E%20UNMAP%5B%22%E8%A7%A3%E6%98%A0%E5%B0%84%E5%B9%B6%E5%86%B2%20TLB%22%5D%0A%20%20UNMAP%20--%3E%20NEW%5B%22%E8%A3%85%E5%85%A5%E7%BC%BA%E7%9A%84%E9%A1%B5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>置换把物理内存当成 Cache：虚页是 Cache 里的块，缺页是缺失。<a href="/cs/locality-principle">局部性</a>再次决定命中率。抖动时<a href="/cs/scheduling-metrics">调度指标</a>全面恶化：利用率看起来高（在等磁盘），用户吞吐接近零。对策是减少多道程度，而不是更频繁切换。</p><p>只读文本可丢弃后从文件再读，不必写回。匿名脏页要进交换区。区分二者靠页的来源，下一课 COW 与 mmap 会细化来源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入工作集窗口的精确调参，不把 NUMA 远程帧当默认模型。Belady 异常提醒：不要用「帧越多越好」在 FIFO 上当定理。也不把缺页率公式与 Cache 缺失分类一一对应成同一组数字。</p><p>第二次机会与时钟是同一族。NRU 用访问/脏两位分四类，教学上当作 LRU 的更粗近似。</p><p>后课默认：帧可被淘汰；脏匿名页走交换。<code>fork</code> 若立即复制所有页太贵，下一课用写时复制推迟复制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无帧则置换；LRU/时钟逼近最优，FIFO 有 Belady 异常。</li><li>脏页写回；抖动要减多道，不靠更小时间片。</li><li>fork 的复制代价是 COW 的缺口。</li><li>出处：Belady, 1966；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',9))])}const b=o(h,[["render",m]]);export{T as __pageData,b as default};
